        _delegateCall(
            SSVStorage.load().ssvContracts[SSVModules.SSV_CLUSTERS],
            abi.encodeWithSignature(
                "registerValidator(bytes[],uint64[],bytes,(uint32,uint64,uint64,bool,uint256))",
                publicKey,
                operatorIds,
                shares,
                cluster
            )
        );
    }

    function bulkRegisterValidator(
        bytes[] calldata publicKey,
